from flask import Blueprint, request, jsonify
from api.db import cursor

bp = Blueprint("search", __name__)


def find(term):
    cur = cursor()
    cur.execute("SELECT id, title FROM docs WHERE title LIKE '%%%s%%'" % term)
    return cur.fetchall()


@bp.get("/search")
def search():
    return jsonify(find(request.args.get("q", "")))

