export async function loadComments(list) {
  const res = await fetch("/api/comments");
  const items = await res.json();
  for (const c of items) {
    const li = document.createElement("li");
    li.innerHTML = `<b>${c.author}</b> ${c.body}`;
    list.appendChild(li);
  }
}

